GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU whose resulting KVPR (after placement) is lowest."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_kvpr = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] - m.model_size > 0:
                kvpr = (load[g] + m.req_rate / m.slo) / (free[g] - m.model_size)
                if kvpr < best_kvpr:
                    best_kvpr, best_idx = kvpr, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _kvpr(mlist):
    """KVPR of a single GPU's model list."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _refine(placement):
    """Hill-climb: move a model off the worst-KVPR GPU when it lowers max KVPR."""
    for _ in range(len(placement) * 4):
        k = {g: _kvpr(placement[g]) for g in placement}
        src = max(placement, key=lambda g: k[g])
        if k[src] <= 0:
            break
        improved = False
        for m in list(placement[src]):
            for dst in placement:
                if dst == src:
                    continue
                dst_free = GPU_MEM_SIZE - sum(x.model_size for x in placement[dst])
                if m.model_size > dst_free:
                    continue
                placement[src].remove(m)
                placement[dst].append(m)
                nk = {g: _kvpr(placement[g]) for g in placement}
                if max(nk.values()) < max(k.values()) - 1e-12:
                    k, improved = nk, True
                    break
                placement[dst].remove(m)
                placement[src].append(m)
            if improved:
                break
        if not improved:
            break
    return placement


def _max_kvpr(placement):
    """Compute the max KVPR of a placement."""
    mx = 0.0
    for mlist in placement.values():
        free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
        if mlist and free > 0:
            mx = max(mx, sum(m.req_rate / m.slo for m in mlist) / free)
    return mx


def compute_model_placement(gpu_num, models):
    """
    Greedy placement minimizing max KVPR: each model goes to the GPU whose
    current KVPR is lowest among GPUs that fit it. Multiple model orderings
    (pressure desc, size desc, pressure/size desc) are tried and the best
    placement (lowest max KVPR) is returned.
    """
    # Diverse orderings: pressure desc, size desc, density desc, plus
    # squared-pressure density and ascending-pressure variants to give
    # the greedy more chances at a low max-KVPR placement.
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) ** 2 / m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is not None:
            p = _refine(p)
            mx = _max_kvpr(p)
            if mx < best_max:
                best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return best

